import math

def check_condition(n):
    """
    Checks if k^2 === 1 (mod n) for all k such that gcd(k, n) = 1 and 1 <= k < n.
    """
    if n < 2:
        return False

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            if (k * k) % n != 1:
                return False
    return True

results = []
for n in range(2, 26):
    if check_condition(n):
        results.append(n)

