import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def test_n(n):
    print(f"--- Testing n = {n} ---")
    is_valid = True

    # We only need to check k in [1, n-1] since k^2 mod n repeats for k > n
    for k in range(1, n):
        if gcd(k, n) == 1:
            k_squared_mod_n = (k * k) % n
            if k_squared_mod_n != 1:
                print(f"FAILED for n={n} with k={k}. {k}^2 = {k*k}. {k*k} mod {n} = {k_squared_mod_n} != 1.")
                is_valid = False
                break

    if is_valid:
        print(f"SUCCESS for n={n}. k^2 mod {n} = 1 for all k coprime to {n}.")

    return is_valid

candidate_n = [2, 3, 4, 6, 8, 12, 24]
